<?php require_once __DIR__.'/../../config/app.php';requireAdmin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('/pages/employees/index.php');$d=['employee_number'=>strtoupper(trim($_POST['employee_number']??'')),'full_name'=>trim($_POST['full_name']??''),'gender'=>$_POST['gender']??'','birth_date'=>$_POST['birth_date']??'','position'=>$_POST['position']??'','salary'=>$_POST['salary']??''];$er=[];foreach(['employee_number','full_name','gender','birth_date','position','salary'] as $k)if($d[$k]==='')$er[$k]='Kolom wajib diisi.';if(strlen($d['employee_number'])>10)$er['employee_number']='Nomor karyawan maksimal 10 karakter.';if(!in_array($d['gender'],['M','F'],true))$er['gender']='Jenis kelamin tidak valid.';if(!in_array($d['position'],['Cashier','Warehouse Staff','Admin'],true))$er['position']='Jabatan tidak valid.';if(!validateDateValue($d['birth_date']))$er['birth_date']='Tanggal lahir tidak valid.';if(!is_numeric($d['salary'])||$d['salary']<0)$er['salary']='Gaji harus berupa angka dan tidak boleh negatif.';$check=$pdo->prepare('SELECT employee_id FROM employees WHERE employee_number=?');$check->execute([$d['employee_number']]);if($check->fetch())$er['employee_number']='Nilai sudah digunakan.';if($er)failForm($er,$d,'/pages/employees/create.php');try{$pdo->beginTransaction();$stmt=$pdo->prepare('INSERT INTO employees (employee_number,full_name,gender,birth_date,position,salary) VALUES (?,?,?,?,?,?)');$stmt->execute(array_values($d));$pdo->commit();$_SESSION['success']='Data berhasil ditambahkan.';redirect('/pages/employees/index.php');}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();if($e->getCode()==='23000')failForm(['form'=>'Data duplikat atau melanggar aturan database.'],$d,'/pages/employees/create.php');throw $e;}